  ('d3a545fb-27be-563e-af5e-ea49a0ddcb1e', null, (select id from public.skills where slug = 'read-g8-figurative-language'), null, 'easy',
   $q$The passage says the clock's "hands froze at twenty minutes past four." What does this mean?$q$, $q$[{"text":"A worker's hands became too cold to fix the clock.","is_correct":false,"misconception_token":"wrong-referent"},{"text":"The pointers on the clock stopped moving at that time.","is_correct":true},{"text":"Ice formed on the clock during a very cold winter.","is_correct":false,"misconception_token":"literal-reading"},{"text":"The clock rang loudly every day at twenty past four.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$The pointers on the clock stopped moving at that time.$q$, $q$A clock's "hands" are its pointers, and "froze" means they stopped, which matches "the clock had stopped." Reading "froze" as ice ignores that the sentence describes the clock breaking down.$q$, 'draft', 'fdde9a57-60d5-59d2-92d7-776db8e6d3c5')
