-- Passage rg8-theme-summary-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('80dfb1b0-074c-54cf-b6e9-ff5726509ef6', 'rg8-theme-summary-p02', (select id from public.skills where slug = 'read-g8-theme-summary'), null,
        '6-8', $q$What the River Knows$q$, $q$The river does not argue with the stone.
It does not shout or push or try to win.
It slides around the edges, cool and slow,
and finds the narrow places to begin.

A hundred springs of snowmelt rush and pass.
A hundred summers shrink it to a thread.
The stone sits still and seems to never change,
as solid as the mountain overhead.

But every drop that brushes by the rock
takes something smaller than a grain of sand.
No single day would show you what is lost.
No single hour would help you understand.

Then come back when your hair has turned to gray,
and kneel beside the water where it bends.
The stone has hollowed to a polished bowl,
a shape the river carved with patient hands.

So when your work seems far too slow to count,
remember what the quiet water knows.
The hardest things give way to steady work,
and something changes every time it flows.$q$, 'draft')
