  ('c9f28323-9d40-530d-a6ee-b06c50ec5a01', null, (select id from public.skills where slug = 'read-g8-theme-summary'), null, 'easy',
   $q$Which statement best expresses the theme of the poem?$q$, $q$[{"text":"People should avoid arguing with those who disagree.","is_correct":false,"misconception_token":"literal-reading"},{"text":"Rivers are stronger than mountains in every way.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"Nature is most beautiful when it is left alone.","is_correct":false,"misconception_token":"topic-not-theme"},{"text":"Small, steady efforts can create great change over time.","is_correct":true}]$q$::jsonb, $q$Small, steady efforts can create great change over time.$q$, $q$The river wears the stone into a bowl one tiny grain at a time, and the last stanza says "the hardest things give way to steady work." The line about not arguing describes how the river moves, not a lesson about people.$q$, 'draft', '80dfb1b0-074c-54cf-b6e9-ff5726509ef6')
