  ('4ab4f5dc-e5eb-5905-9b16-2e8293f0fac5', null, (select id from public.skills where slug = 'read-g8-word-parts'), null, 'medium',
   $q$The prefix im- can mean "in" or "into," and port means "carry." What does it mean that workers "imported steel beams"?$q$, $q$[{"text":"They shipped the beams out to another state.","is_correct":false,"misconception_token":"confuses-opposite-prefix"},{"text":"They made the beams themselves at a local mill.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"They brought the beams in from another place.","is_correct":true},{"text":"They thought the beams were very important.","is_correct":false,"misconception_token":"confuses-similar-word"}]$q$::jsonb, $q$They brought the beams in from another place.$q$, $q$Im plus port means "carry in," and the beams came "from a mill in another state." Shipping them out would be exporting, which uses the opposite prefix ex, meaning out.$q$, 'draft', '873d0846-6a26-5ef2-8825-d99f8b2550f5')
