values
  ('4b9d85a9-ab84-5862-8bfa-eb6cf2e627ac', null, (select id from public.skills where slug = 'read-g9-argument-evidence'), null, 'hard',
   $q$Which additional evidence would most strengthen the author's claim that lifting stones harms creek life?$q$, $q$[{"text":"A list of other parks where rangers build rock piles on trails.","is_correct":false,"misconception_token":"irrelevant-detail"},{"text":"A count of how many photographs visitors post of the rock towers.","is_correct":false,"misconception_token":"irrelevant-detail"},{"text":"A comparison of creatures under stones in stacked and unstacked areas.","is_correct":true},{"text":"A survey asking visitors whether they enjoy seeing rock towers.","is_correct":false,"misconception_token":"irrelevant-detail"}]$q$::jsonb, $q$A comparison of creatures under stones in stacked and unstacked areas.$q$, $q$The biologist counted only an undisturbed section, so a comparison with areas where stones were stacked would show whether stacking actually reduces creek life. A survey of opinions would not show any harm.$q$, 'draft', 'b216a66a-35df-58fb-bf9d-6c70662ac876')
