  ('da218e9c-f694-5ebb-a96b-49e2273bf74e', null, (select id from public.skills where slug = 'read-g9-authors-purpose'), null, 'hard',
   $q$Why does the author open with Castellanos's goal before turning to Raman's pass?$q$, $q$[{"text":"The author wants to show that the goal was the most important event of the game and the pass mattered far less.","is_correct":false,"misconception_token":"reverses-viewpoint"},{"text":"The author hopes to convince readers that Castellanos should share his award with Raman at the end of the season.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The author starts with the moment readers already remember, then shifts to the one they missed, which makes the point stand out.","is_correct":true},{"text":"The author is organizing the column in strict time order, describing events in the order in which they happened.","is_correct":false,"misconception_token":"confuses-structure"}]$q$::jsonb, $q$The author starts with the moment readers already remember, then shifts to the one they missed, which makes the point stand out.$q$, $q$The familiar goal sets up the contrast with "a different moment... that almost nobody cheered." The pass happened thirty seconds before the goal, so the column is not in time order.$q$, 'draft', 'ed8d4aa5-ea67-5d94-b46e-4997ce84cee9')
