  ('a102ce54-74fa-57ab-9aff-dcf01adb0131', null, (select id from public.skills where slug = 'read-g9-authors-purpose'), null, 'hard',
   $q$How do the closing sentences, "Our office cannot reach into every backyard. You can," support the author's purpose?$q$, $q$[{"text":"The sentences warn residents that county workers will soon inspect each backyard for water.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The short contrast presents residents as necessary partners who can do what the county cannot.","is_correct":true},{"text":"The contrast admits that the health department has given up on controlling mosquitoes this year.","is_correct":false,"misconception_token":"overstates-claim"},{"text":"The sentences suggest that residents are to blame for every mosquito bite in the county.","is_correct":false,"misconception_token":"misreads-tone"}]$q$::jsonb, $q$The short contrast presents residents as necessary partners who can do what the county cannot.$q$, $q$Placing "cannot" beside "You can" hands residents a role only they can fill, which matches the author's thanks to "our partners." The county will keep spraying when needed, so it has not given up.$q$, 'draft', '5344bbe8-db9c-50be-8140-c9dadbd13a83')
